File ExternalPresetImport::defaultLibraryRoot(){auto plugins=File::getSpecialLocation(File::userDesktopDirectory).getChildFile("VST3 Plugins");auto preferred=plugins.getChildFile("Nexum/Packs");if(preferred.isDirectory())return preferred;for(auto& folder:plugins.findChildFiles(File::findDirectories,false))if(folder.getChildFile("Packs").isDirectory())return folder.getChildFile("Packs");return preferred;}
PackResult ExternalPresetImport::importPack(const File& file,const File& libraryRoot){PackResult r;ZipFile zip(file);if(zip.getNumEntries()<=0||zip.getNumEntries()>4096){r.error="Invalid or oversized SerumPack archive";return r;}int64 total=0;for(int i=0;i<zip.getNumEntries();++i){const auto* e=zip.getEntry(i);if(!validRelative(e->filename)||e->uncompressedSize<0||e->uncompressedSize>128*1024*1024){r.error="Unsafe archive path or asset too large";return r;}total+=e->uncompressedSize;if(total>1024LL*1024*1024){r.error="Pack exceeds 1 GB extraction limit";return r;}}
 String name=File::createLegalFileName(file.getFileNameWithoutExtension());if(name.isEmpty())name="ImportedPack";r.root=libraryRoot.getChildFile(name);if(r.root.exists())r.root=r.root.getNonexistentSibling();if(!r.root.createDirectory()){r.error="Cannot create pack library folder";return r;}
 for(int i=0;i<zip.getNumEntries();++i){auto* e=zip.getEntry(i);String ext=File(e->filename).getFileExtension().toLowerCase();if(ext!=".serumpreset"&&ext!=".wav"&&ext!=".json"&&ext!=".png")continue;auto result=zip.uncompressEntry(i,r.root,false);if(result.failed()){r.error=result.getErrorMessage();return r;}if(ext==".wav")++r.assets;}
 auto presets=r.root.findChildFiles(File::findFiles,true,"*.SerumPreset");presets.sort();String report="NoCTRL SerumPack import compatibility report\nSource: "+file.getFileName()+"\n\nPresets are APPROXIMATIONS, not Serum-equivalent sounds. Missing assets and unsupported features are listed per preset.\n\n";
 for(const auto& preset:presets){auto result=readPreset(preset,r.root);report+=preset.getFileName()+"\n";if(result.ok){++r.presets;r.names.add(result.name);for(auto& warning:result.warnings)report+="  - "+warning+"\n";}else report+="  ERROR: "+result.error+"\n";report+="\n";}
 r.report=r.root.getChildFile("NoCTRL-Import-Report.txt");r.report.replaceWithText(report);r.ok=r.presets>0;if(!r.ok)r.error="No readable Nexum presets found";return r;}
